// Amplify setup. amplify_outputs.json is generated by the backend deploy and is never committed,
// so it is loaded optionally: without it the public tabs still work and private screens say so.
import { Amplify } from "aws-amplify";
import { fetchAuthSession } from "aws-amplify/auth";
import { generateClient } from "aws-amplify/data";
import type { Schema } from "../../amplify/data/resource.ts";
import { localMode } from "./localMode.ts";

const found = import.meta.glob("../../amplify_outputs.json", { eager: true, import: "default" });
// Local dev mode ignores any amplify_outputs.json, so it never talks to AWS.
const outputs = localMode ? undefined : (Object.values(found)[0] as Parameters<typeof Amplify.configure>[0] | undefined);

export const backendConfigured = outputs !== undefined;

// Campaign access is matched on the email claim, which only the ID token carries. Amplify sends the
// access token by default, so swap in the ID token for every query, mutation and subscription.
if (outputs) {
  Amplify.configure(outputs, {
    API: {
      GraphQL: {
        headers: async (): Promise<Record<string, string>> => {
          const idToken = (await fetchAuthSession()).tokens?.idToken?.toString();
          return idToken ? { Authorization: idToken } : {};
        },
      },
    },
  });
}

let client: ReturnType<typeof generateClient<Schema>> | undefined;

/** The typed Amplify Data client. Only call when `backendConfigured` is true. */
export function dataClient() {
  client ??= generateClient<Schema>({ authMode: "userPool" });
  return client;
}
